            if(preg_match('/^[A-Za-z0-9_]+$/D',$prefix)!==1||preg_match('/^[A-Za-z0-9_]+$/D',$legacy)!==1)throw new RuntimeException();
            $db=new mysqli(getenv('FMONITOR_DB_HOST')?:'127.0.0.1',(string)getenv('FMONITOR_DB_USER'),(string)getenv('FMONITOR_DB_PASSWORD'),(string)getenv('FMONITOR_DB_NAME'),(int)(getenv('FMONITOR_DB_PORT')?:3306));$db->set_charset('utf8mb4');
            $userId=filter_var($_SERVER['FMONITOR_AUTH_USER_ID']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($userId===false)throw new RuntimeException('AUTHENTICATED_USER_ID_MISSING');$userQuery=$db->prepare("SELECT user_id,full_name,email FROM `{$prefix}fm2_pilot_users` WHERE user_id=? AND status=1 LIMIT 1");$userQuery->bind_param('i',$userId);$userQuery->execute();$row=$userQuery->get_result()->fetch_assoc();if(!is_array($row))throw new RuntimeException('AUTHENTICATED_USER_NOT_FOUND');$permissions=\FMonitor2\PilotHttp\AccessPolicy::forUser($db,$prefix,(int)$row['user_id']);if(!\FMonitor2\PilotHttp\AccessPolicy::grants($permissions,\FMonitor2\PilotHttp\AccessPolicy::OBJECTS_READ))self::respond(403,"Access denied.\n",'text/plain; charset=UTF-8');$user=new \FMonitor2\PilotHttp\HttpUser((int)$row['user_id'],(string)$row['full_name'],(string)$row['email'],$permissions);
            RapidPilotInspectionSchedule::assertSchemaReady($db,$prefix);RapidPilotCompletionFlow::ensureQueueSchema($db,$prefix);[$objects,$filters]=self::readObjects($db,$prefix,$legacy);
            $caps=[];foreach(['assignment_order.prepare','assignment_order.confirm_registration','installation.open']as$cap)$caps[$cap]=$user->can($cap);$canProvideOrder=$caps['assignment_order.prepare']||$caps['assignment_order.confirm_registration'];$allowed=['Требуется распоряжение'=>$canProvideOrder,'Готов к открытию'=>$caps['installation.open']];
            foreach($objects as&$object){if(($object['status']??null)==='Распоряжение подготовлено')$object['status']='Требуется распоряжение';$status=(string)$object['status'];$object['nextStep']=($allowed[$status]??($status==='В работе'))?match($status){'Требуется распоряжение'=>'Загрузить оригинал распоряжения','Готов к открытию'=>'Открыть работы','В работе'=>'Инженеру: провести первую инспекцию',default=>'Откройте карточку объекта монтажа'}:'Откройте карточку объекта монтажа';}unset($object);$objects=RapidPilotCompletionFlow::decorateQueue($objects,$db,$prefix);foreach($objects as&$object)if(($object['status']??null)==='Монтажные работы')$object['status']='В работе';unset($object);$canSchedule=RapidPilotInspectionSchedule::canSchedule($db,$prefix,$user->id);$db->close();
            $html=self::render($user,$objects,$filters,$canSchedule,(string)($_SERVER['FMONITOR_AUTH_CSRF']??''));$html=RapidPilotCompletionFlow::paintStatuses($html);$html=RapidPilotShell::decorate($html,(string)($_SERVER['FMONITOR_AUTH_CSRF']??''),false,RapidPilotOtiz::currentUserCanAccess(),false);$html=str_replace('</head>','<link rel="icon" type="image/svg+xml" href="/pilot/assets/favicon.svg"></head>',$html);$html=str_replace('</body>','<script type="module" src="/pilot/assets/object-queue.js"></script><script src="/pilot/assets/inspection-schedule.js" defer></script></body>',$html);self::respond(200,$html);
        } catch(Throwable $error) {
