        }
    }

    private static function readObjects(mysqli$db,string$prefix,string$legacy):array
    {
        $q=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'');$page=filter_var($_GET['page']??1,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$allowed=['','needs_assignment_order','ready_to_open','installation','document_closeout','completed','needs_assignment_change'];if(mb_strlen($q)>120||$page===false||!in_array($status,$allowed,true))throw new RuntimeException('OBJECT_QUEUE_FILTER_INVALID');
        $progressCount="(SELECT COUNT(DISTINCT co.item_id) FROM `{$prefix}fm2_checklist_operations` co WHERE co.installation_case_id=c.id AND co.operation_type='item_completed' AND co.item_id<>42)";$hasPto="EXISTS(SELECT 1 FROM `{$prefix}fm2_pilot_completion_facts` cf WHERE cf.installation_case_id=c.id AND cf.fact_type='pto_act')";$hasDeclaration="EXISTS(SELECT 1 FROM `{$prefix}fm2_pilot_completion_facts` cf WHERE cf.installation_case_id=c.id AND cf.fact_type='declaration')";$active="c.process_state IN('working','needs_assignment_change') AND o.status IN('prepared','registered')";
        $statusSql=match($status){'needs_assignment_order'=>"(c.process_state='needs_assignment_order' AND o.id IS NULL) OR (c.process_state='assignment_order_prepared' AND o.status='prepared')",'ready_to_open'=>"c.process_state='assignment_order_prepared' AND o.status='registered'",'installation'=>"{$active} AND {$progressCount}<41",'document_closeout'=>"{$active} AND {$progressCount}=41 AND NOT({$hasPto} AND {$hasDeclaration})",'completed'=>"{$active} AND {$hasPto} AND {$hasDeclaration}",'needs_assignment_change'=>"c.process_state='needs_assignment_change' AND o.status='registered'",default=>'1=1'};$where="m.category='native_candidate' AND ({$statusSql})";if($q!==''){$like='%'.str_replace(['\\','%','_'],['\\\\','\\%','\\_'],$q).'%';$like=$db->real_escape_string($like);$where.=" AND (CAST(c.legacy_installation_object_id AS CHAR) LIKE '{$like}' ESCAPE '\\\\' OR l.regnumber LIKE '{$like}' ESCAPE '\\\\' OR l.ordadr_address LIKE '{$like}' ESCAPE '\\\\' OR l.entrance LIKE '{$like}' ESCAPE '\\\\')";}
        $from=" FROM `{$prefix}fm2_installation_cases` c JOIN `{$legacy}fm_maintable` l ON l.id=c.legacy_installation_object_id JOIN `{$prefix}fm2_migration_classification_provenance` m ON m.output_kind='operational_case' AND m.output_id=c.id AND m.legacy_object_id=c.legacy_installation_object_id LEFT JOIN `{$prefix}fm2_assignment_orders` o ON o.installation_case_id=c.id AND o.version_no=(SELECT MAX(latest.version_no) FROM `{$prefix}fm2_assignment_orders` latest WHERE latest.installation_case_id=c.id) WHERE {$where}";$total=(int)$db->query("SELECT COUNT(*) n{$from}")->fetch_assoc()['n'];$pages=max(1,(int)ceil($total/50));if($page>$pages)throw new RuntimeException('OBJECT_QUEUE_PAGE_INVALID');$offset=($page-1)*50;$rows=$db->query("SELECT c.legacy_installation_object_id,c.process_state,c.actual_start_date,c.opened_at,c.opened_by_user_id,l.ordadr_address,l.entrance,l.regnumber,l.workdatestart,l.workdateendadjusted,l.plan_finish_date,o.status order_status{$from} ORDER BY l.workdatestart IS NULL,LEFT(l.workdatestart,10),c.legacy_installation_object_id LIMIT 50 OFFSET {$offset}")->fetch_all(MYSQLI_ASSOC);$objects=[];foreach($rows as$row){$opening=[$row['actual_start_date'],$row['opened_at'],$row['opened_by_user_id']];$opened=count(array_filter($opening,static fn(mixed$v):bool=>$v!==null))===3;$empty=count(array_filter($opening,static fn(mixed$v):bool=>$v!==null))===0;$order=$row['order_status'];$label=match((string)$row['process_state']){'needs_assignment_order'=>$empty&&$order===null?'Требуется распоряжение':null,'assignment_order_prepared'=>$empty&&$order==='prepared'?'Распоряжение подготовлено':($empty&&$order==='registered'?'Готов к открытию':null),'working'=>$opened&&in_array($order,['prepared','registered'],true)?'В работе':null,'needs_assignment_change'=>$opened&&in_array($order,['prepared','registered'],true)?'В работе':null,default=>null};$id=(int)$row['legacy_installation_object_id'];$start=self::date($row['workdatestart']);$finish=self::date($row['workdateendadjusted'])??self::date($row['plan_finish_date']);if($id<1||$label===null||trim((string)$row['ordadr_address'])===''||trim((string)$row['entrance'])===''||trim((string)$row['regnumber'])===''||$start===null||$finish===null)throw new RuntimeException('OBJECT_QUEUE_ROW_INVALID:'.$id);$objects[]=['id'=>$id,'registrationNumber'=>(string)$row['regnumber'],'address'=>(string)$row['ordadr_address'],'entrance'=>(string)$row['entrance'],'plannedStartDate'=>$start,'plannedFinishDate'=>$finish,'planningDatesUnknownAtCutover'=>false,'dataOrigin'=>'migration_native','status'=>$label,'_pagination'=>['page'=>(int)$page,'pages'=>$pages,'total'=>$total,'pageSize'=>50,'origin'=>'all']];}return[$objects,['q'=>$q,'status'=>$status,'page'=>(int)$page,'pages'=>$pages,'total'=>$total]];
    }

    private static function date(mixed$value):?string{$value=trim((string)$value);if(preg_match('/^(\d{4})-(\d{2})-(\d{2})(?:\D|$)/D',$value,$parts)!==1||$parts[1]==='0000'||!checkdate((int)$parts[2],(int)$parts[3],(int)$parts[1]))return null;return$parts[1].'-'.$parts[2].'-'.$parts[3];}

